module accu(
    input clk, input rst_n, input [7:0] data_in, input valid_in,
    output reg valid_out, output reg [9:0] data_out
);
// TODO: Your implementation here
reg [1:0] cnt;
reg [9:0] sum;
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		cnt <= 2'd0;
		sum <= 10'd0;
	end
	else if(valid_in && cnt != 2'd3) begin
		cnt <= cnt + 2'd1;
		sum <= sum + data_in;
	end
	else if(cnt == 2'd3) begin
		cnt <= 2'd0;
		sum <= 10'd0;
	end
end
always@(*) begin
	if(cnt == 2'd3)
		valid_out = 1'b1;
	else
		valid_out = 1'b0;
end
always@(posedge clk) begin
	if(valid_out)
		data_out <= sum;
end
endmodule
